import {sanitizeState} from './model.js?v=0.31.0';
import {profileQuestions,saveProfileAnswer,broadSuggestions,professionSuggestions,profileComplete,lifestyleComplete,depthComplete,makeJourneyPlan} from './profile-journey.js?v=0.31.0';
import {professionQuestions} from './profession-questions.js?v=0.31.0';
import {careerFamilies,applyGuidePay} from './guide-state.js?v=0.31.0';
import {lifestyleChoices,buildLifestyleInputs,builderReady} from './lifestyle-builder.js?v=0.31.0';
import {occupationById} from './occupation-data.js?v=0.31.0';
import {priorities} from './content.js?v=0.31.0';
import {scoreOnetInterest,matchingEngineVersion} from './onet-assessment.js?v=0.31.0';
import {salaryPreviewStages} from './salary-progression.js?v=0.31.0';
import {studentReviewInputs,studentReviewPlan} from './developer-review-data.js?v=0.31.0';
export const cloneExperiment=s=>structuredClone(s);
const unique=values=>[...new Set(values)];
export function changeExperimentFamily(state,family){if(!careerFamilies.some(f=>f.id===family))throw Error('Choose a listed field.');const next=cloneExperiment(state);next.profileJourney.family=family;return next;}
export function editExperimentAnswer(state,group,id,values){if(!Array.isArray(values))throw Error('Choose an answer.');values=unique(values);const next=cloneExperiment(state),j=next.profileJourney;
 if(group==='housing'){if(id!=='homeMode'||values.length!==1||!['rent','own'].includes(values[0]))throw Error('Choose renting or owning.');next.guide.lifestyleBuilder.homeMode=values[0];}
 else if(group==='lifestyle'){const q=lifestyleChoices.find(q=>q.id===id);if(!q||values.length>1||values.some(v=>!Number.isInteger(v)||v<0||v>4))throw Error('Choose a listed lifestyle option.');if(values.length)next.guide.lifestyleBuilder.choices[id]=values[0];else delete next.guide.lifestyleBuilder.choices[id];}
 else if(group==='profile'){const q=profileQuestions.find(q=>q.id===id);if(!q)throw Error('Question not found.');if(q.kind==='values'){if(values.length>3||values.some(v=>!priorities.some(p=>p.id===v)))throw Error('Choose up to three listed work values.');next.priorities=values;j.answers.values=true;}
  else if(q.kind==='context'&&q.multi){if(values.some(v=>!q.options.some(([key])=>key===v)))throw Error('Choose a listed option.');j.answers[id]=values;}
  else{if(values.length>1)throw Error('Choose one answer.');if(!values.length){if(q.kind==='interest')delete j.officialInterest.answers[id];else if(q.kind==='pathway')delete j.fieldPreferences[id];else if(q.kind==='skill')delete j.skills[id];else delete j.answers[id];}else if(!saveProfileAnswer(next,q,values[0]))throw Error('Choose a listed answer.');}}
 else if(group==='followup'){const q=(professionQuestions[j.family]||[]).find(q=>q.id===id);if(!q||values.some(v=>!q.options.some(o=>o.id===v)))throw Error('Choose a listed follow-up answer.');j.depth[j.family]??={};j.depth[j.family][id]=values;}
 else throw Error('Question group not found.');
 if(['housing','lifestyle'].includes(group)){const b=next.guide.lifestyleBuilder;b.complete=builderReady(b);if(b.complete){next.finance.lifestyle=buildLifestyleInputs(b,next.finance.lifestyle);next.guide.lifestylePreset='custom';}}
 return next;
}
function matchingSignature(s){const j=s.profileJourney;return JSON.stringify([profileQuestions.filter(q=>['interest','pathway'].includes(q.kind)).map(q=>q.kind==='interest'?j.officialInterest.answers[q.id]??null:j.fieldPreferences[q.id]??null),j.family,(professionQuestions[j.family]||[]).map(q=>Array.isArray(j.depth[j.family]?.[q.id])?[...j.depth[j.family][q.id]].sort():null)]);}
export function experimentSnapshot(state,{plan=null,planReason='Original case plan.'}={}){const s=cloneExperiment(state),p=scoreOnetInterest(s),b=broadSuggestions(s),r=professionSuggestions(s),inputs=studentReviewInputs(s);return {matchingEngineVersion,rawScores:p.raw,flat:p.flat,nearFlat:p.nearFlat,profileComplete:profileComplete(s),lifestyleComplete:lifestyleComplete(s),followupsComplete:depthComplete(s),status:r.status,family:s.profileJourney.family,pathways:b.fields.map(f=>({id:f.id,title:f.title,r:f.connection.score})),workPathways:b.workFields.map(f=>({id:f.id,title:f.title,r:f.connection.score})),fieldComparisons:b.ranked.map(f=>({id:f.id,title:f.title,r:f.connection.baseRoles.length?f.connection.score:null,featured:b.fields.some(x=>x.id===f.id),workConfirmed:f.connection.focused.confirmed,conflict:f.connection.conflicting,disliked:f.connection.focused.concerns.map(q=>q.summary)})),professions:r.top.map(x=>({id:x.o.id,title:x.o.finance?.title||x.o.title,r:x.interestMatch.r,basis:x.basis,reasons:x.reasons})),taskLed:r.taskLeads.map(x=>({id:x.o.id,title:x.o.finance?.title||x.o.title})),sharedTaskAlternatives:r.rows.filter(x=>x.comparisonOnly).map(x=>({id:x.o.id,title:x.o.finance?.title||x.o.title,sharedWith:x.sharedTaskAlternatives})),inputs,plan,planReason};}
export function originalExperiment(state){return experimentSnapshot(state,{plan:state.guide.primaryCareer?studentReviewPlan(state):null});}
export function rerunExperiment(original,draft,{planChoice='adapt',salaryStage='auto'}={}){const input=sanitizeState(cloneExperiment(draft)),matches=professionSuggestions(input),originalCareer=original.guide.primaryCareer,unchanged=matchingSignature(original)===matchingSignature(input);let career=null,reason='No plan preview: no supported career was selected.';
 if(planChoice==='adapt'){career=originalCareer&&(unchanged||matches.top.some(row=>row.o.id===originalCareer))?originalCareer:(matches.top.length===1?matches.top[0]?.o.id:null);reason=career===originalCareer?(unchanged?'Original scenario career retained; matching answers are unchanged.':'Original career remains suggested.'):career?'Developer preview of the first supported career. This is not an automatic student decision.':reason;if(!depthComplete(input)&&!unchanged){career=null;reason='Finish the selected field’s follow-ups, or mark them not sure, before an automatic plan preview.';}}
 else if(planChoice==='none'){reason='No plan requested. Keep the career choice open.';}
 else if(planChoice==='original'){career=originalCareer;reason='Original career kept as an explicit choice, whether or not it is suggested.';}
 else if(planChoice.startsWith('career:')){career=planChoice.slice(7);if(!occupationById(career))throw Error('Choose a listed career.');reason='Explicit developer career preview; this choice is not a recommendation.';}
 else throw Error('Choose a listed plan mode.');
 if(planChoice==='adapt'&&!career&&depthComplete(input)){if(matches.top.length>1)reason='Several careers fit the answers. Choose a career to compare its plan; no first-career plan is assigned.';else if(matches.status==='open-profile')reason='The interest pattern is still open. No career is assigned.';else if(matches.rows.some(r=>r.specificSupport>=2&&r.routeConflict))reason='The preferred clinical work and preparation route conflict. Compare those choices before selecting a career.';else if(matches.status==='preference-conflict')reason='Daily-work preferences conflict with this field. No automatic plan is assigned.';else if(matches.status==='broad')reason='Several roles remain tied or the answers are too broad. No arbitrary career plan is assigned.';}
 if(!profileComplete(input)||!lifestyleComplete(input)){career=null;reason='Complete the profile and lifestyle choices before previewing a career plan.';}
 const planState=cloneExperiment(input);let plan=null;
 if(career&&makeJourneyPlan(planState,career)){if(salaryStage!=='auto'){if(!salaryPreviewStages(career).some(s=>s.key===salaryStage))throw Error('That pay stage is unavailable for this career.');planState.guide.salaryStage=salaryStage;applyGuidePay(planState);}plan=studentReviewPlan(planState);if(!matches.top.some(row=>row.o.id===career))reason+=' This career is not among the current suggestions.';}
 return {...experimentSnapshot(input,{plan,planReason:reason}),inputState:input,planState:plan?planState:null};
}
export function answerChanges(original,current){const a=studentReviewInputs(original),b=studentReviewInputs(current),changes=[];if(original.guide.lifestyleBuilder.homeMode!==current.guide.lifestyleBuilder.homeMode)changes.push({prompt:'Housing: rent or own',before:original.guide.lifestyleBuilder.homeMode,after:current.guide.lifestyleBuilder.homeMode});if(a.family!==b.family)changes.push({prompt:'Field for profession follow-ups',before:careerFamilies.find(f=>f.id===a.family)?.title,after:careerFamilies.find(f=>f.id===b.family)?.title});for(const group of ['lifestyle','profile','followups'])for(const q of b[group]){const previous=a[group].find(x=>x.id===q.id);if(q.answer!==(previous?.answer||'Not asked in original case'))changes.push({prompt:q.prompt,before:previous?.answer||'Not asked in original case',after:q.answer});}return changes;}
